// One item per advert from the Reed API, shaped for ingest_signal. Signal type comes from the search that found it.
// Reed search results (observed): jobId, employerName, employerId, jobTitle, locationName, minimumSalary, maximumSalary, currency, date (DD/MM/YYYY), expirationDate, jobDescription, applications, jobUrl.
// hiring_resourcer searches are keyword matches and very loose, so the TITLE must look like an agency hiring for its own desk.
const RESOURCER = /\bresourc(er|ing)\b|recruit(ment|ing)? (administrator|coordinator|co-ordinator|assistant|consultant|resourcer)|delivery consultant|trainee recruit|graduate recruit|360 recruit|recruitment executive|talent (acquisition|partner|consultant)/i;
const CLIENT_SIDE = /\bin-?house\b|\binternal\b|\bHR\b|human resources|people (partner|advisor|coordinator)/i;
const seen = new Set();
const out = [];
const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const resp = all[i].json;
  let search = {};
  try { search = $('Build searches').all()[i].json; } catch (e) {}
  const results = Array.isArray(resp.results) ? resp.results : [];
  for (const j of results) {
    const name = String(j.employerName || '').trim();
    const id = j.jobId;
    if (!name || !id) continue;
    const title = String(j.jobTitle || '');
    const type = search.signal_type || 'job_advert';
    if (type === 'hiring_resourcer' && (!RESOURCER.test(title) || CLIENT_SIDE.test(title))) continue;
    const url = j.jobUrl || ('https://www.reed.co.uk/jobs/' + id);
    const key = type + '|' + url;
    if (seen.has(key)) continue;
    seen.add(key);
    let seen_at = new Date().toISOString();
    const m = String(j.date || '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (m) seen_at = new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])).toISOString();
    const pay = (j.minimumSalary || j.maximumSalary) ? ('£' + [j.minimumSalary, j.maximumSalary].filter(Boolean).map(n => Number(n).toLocaleString('en-GB')).join(' - ')) : '';
    const apps = (j.applications === 0 || j.applications) ? Number(j.applications) : null;
    const summary = String(j.jobDescription || '').replace(/\s+/g, ' ').trim().slice(0, 300);
    const bits = [title, j.locationName, pay, apps !== null ? apps + ' applications' : ''].filter(Boolean);
    out.push({ json: {
      name,
      region: j.locationName || search.location || null,
      source_url: url,
      detail: bits.join(' | ') + (summary ? ' | ' + summary : ''),
      seen_at,
      signal_type: type,
      applications: apps
    } });
  }
}
return out;

// Same normalisation as ops.normalise_company_name in Supabase. Exact match first, then prefix, else none.
const a = $('Load agencies to score').item.json;
const norm = s => String(s || '').toLowerCase().replace(/\b(ltd|limited|llp|plc|uk|group|holdings)\b/g, '').replace(/[^a-z0-9]/g, '');
const items = Array.isArray($json.items) ? $json.items : [];
const target = norm(a.name);
const active = items.filter(i => i.company_status === 'active');
const exact = active.find(i => norm(i.title) === target);
const prefix = active.find(i => target.length >= 6 && (norm(i.title).startsWith(target) || target.startsWith(norm(i.title))));
const m = exact || prefix || null;
return { json: {
  ...a,
  company_number: m ? m.company_number : null,
  ch_name: m ? m.title : null,
  incorporated_on: m ? m.date_of_creation : null,
  ch_locality: (m && m.address && m.address.locality) ? m.address.locality : null,
  ch_match: exact ? 'exact' : (prefix ? 'prefix' : 'none')
} };

// Fan-in: matched agencies arrive from Enrich (via Pick owner), unmatched straight from the IF. One shape for the scorer.
let a = null;
try { a = $('Pick owner').item.json; } catch (e) {}
if (!a || !a.agency_id) a = $('Pick CH match').item.json;
return { json: { ...a } };

// One item per (keyword, location, signal type). Reed is searched once per item, 100 results each, agencies only.
const c = $input.first().json;
const split = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const out = [];
for (const location of split(c.locations)) {
  for (const keywords of split(c.search_terms)) out.push({ json: { keywords, location, signal_type: 'job_advert', distance: Number(c.distance_miles) || 15, take: Number(c.results_per_query) || 100 } });
  for (const keywords of split(c.resourcer_terms)) out.push({ json: { keywords, location, signal_type: 'hiring_resourcer', distance: Number(c.distance_miles) || 15, take: Number(c.results_per_query) || 100 } });
}
return out;

// Owner = longest-serving active director who is a person (corporate officers have no comma). Name observed as 'SURNAME, Forename Middle'.
const a = $('Pick CH match').item.json;
let profile = {};
try { profile = $('Companies House profile').item.json || {}; } catch (e) {}
const items = Array.isArray($json.items) ? $json.items : [];
const active = items.filter(o => !o.resigned_on && /director|llp-member|member/.test(String(o.officer_role || '')));
const people = active.filter(o => String(o.name || '').includes(','));
people.sort((x, y) => String(x.appointed_on || '9999').localeCompare(String(y.appointed_on || '9999')));
const tc = s => String(s || '').toLowerCase().replace(/(^|[\s-'])\S/g, m => m.toUpperCase());
let owner_name = null, owner_role = null;
if (people.length) {
  const parts = String(people[0].name).split(',');
  const surname = tc(parts[0].trim());
  const forename = tc(parts.slice(1).join(',').trim().split(/\s+/)[0]);
  owner_name = (forename + ' ' + surname).trim();
  owner_role = people[0].occupation || people[0].officer_role || null;
}
return { json: { ...a, sic_codes: Array.isArray(profile.sic_codes) ? profile.sic_codes : null, owner_name, owner_role, active_directors: active.length, directors_all: people.map(p => p.name) } };
